namespace WallstopStudios.UnityHelpers.CheckControls
{
    using System;
    using UnityEngine;
    using WallstopStudios.UnityHelpers.Core.Serialization.WallstopProto;

    public struct ControlMissingEquality { }

    [WProtoContract]
    internal sealed class ControlContractIsNotPartial
    {
        [WProtoMember(1)]
        public int value;
    }

    internal static class ControlNullPropagation
    {
        internal static readonly Type Anchor = typeof(Example.Anchor);

        internal static string NameOf(Transform target)
        {
            return target?.name;
        }

        internal static int Retrieve(System.Collections.Generic.Queue<int> values)
        {
            return values.Dequeue();
        }

        internal static int Snapshot(System.Collections.Generic.ICollection<int> values)
        {
            if (values.Count > 0)
            {
                return values.Count;
            }
            return 0;
        }

        internal static bool Logic(bool left, bool right)
        {
            return left | right;
        }

        internal static int Sum(int[] values)
        {
            int total = 0;
            for (int index = 0; index < values.Length; index++)
            {
                total += values[index];
            }
            return total;
        }
    }
}

